{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C07"],
      "claim": "Olsalazine, a salicylate-derived azo compound, has systemic availability of only 2.3% after a 1 g oral dose in fasting healthy volunteers, directly demonstrating that salicylate-based aromatic structures can be very poorly absorbed.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Rebamipide, an aromatic amide containing a chlorophenyl group, has oral bioavailability under 10% in humans, supporting low systemic absorption for the query's chlorinated amide scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Phosphanilic acid, an aniline-derived polar aromatic, has about 4% oral bioavailability in humans, indicating that aniline/aromatic polar structures can be poorly absorbed.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Methyl parathion, a nitroaromatic compound, has estimated oral bioavailability <1.7% in a human case, supporting the absorption-limiting effect of the nitroaryl moiety present in the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Ferulic acid, a phenolic acid, shows only 3-10% oral bioavailability in humans, supporting low F for phenolic/aromatic acid-like scaffolds.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Salicylic acid has near-complete oral bioavailability (f=0.92) in humans; however, this reflects the small free carboxylic acid and is not representative of the query's larger amide/nitro structure.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a lipophilic salicylanilide with a nitro group and amide linkage. Multiple high-transfer human bioavailability records for structurally related aromatic amides, salicylate derivatives, nitroaromatics, and phenolic acids show F <10%, well below the 20% threshold. The only high-F evidence (salicylic acid) is for a small free carboxylic acid that lacks the amide/nitro/chloro substituents of the query and is not representative of its absorption behavior. Therefore low oral bioavailability is better supported.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for the query molecule itself; extrapolation relies on analogues.",
    "The high-F salicylate evidence is not mechanistically transferable due to absence of a free carboxylate and the larger amide/nitro structure of the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

